function frame(now){if(playing&&sim){if(last)acc+=Math.min(.1,(now-last)/1000);last=now;while(acc>=1/60&&sim.time<winner.config.duration-1e-7){compactEngine.tick(sim);acc-=1/60}drawField();drawChart();if(sim.time>=winner.config.duration-1e-7){playing=false;$('replay').disabled=false;if(sim.collisions!==winner.score)$('resultNote').textContent+=' Replay verification mismatch; rerun the experiment.'}}requestAnimationFrame(frame)}new ResizeObserver(()=>{drawField();drawChart();drawEvolution();drawLandscape()}).observe($('results'));requestAnimationFrame(frame);

